        ready = sorted(name for name, d in remaining.items() if not d)
        if not ready:
            fail("dependency cycle among: %s" % ", ".join(sorted(remaining)))
        for name in ready:
            order.append(name)
            del remaining[name]
        for d in remaining.values():
