import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
_FALSE_KEYS = ("complete", "checkout", "committed", "ok")
_NONEMPTY_KEYS = ("unavailable", "missing", "conflicts", "unreachable")


def _attention(components):
    names = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.add(name)
        for key in _FALSE_KEYS:
            if key in result and result[key] is False:
                names.add(name)
        for key in _NONEMPTY_KEYS:
            value = result.get(key)
            if isinstance(value, (list, dict, str, tuple, set)) and len(value) > 0:
                names.add(name)
    return sorted(names)


def build_report(core):
    if not isinstance(core, dict) or not isinstance(core.get("components"), dict):
        raise ValueError("bad core manifest")
    components = core["components"]
    serialized = json.dumps(
        core, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    digest = hashlib.sha256(serialized).hexdigest()
    return {
        "title": "三种挂载格式的离线事实归并",
        "component_count": len(components),
        "sha256": digest,
        "attention": _attention(components),
    }


def main():
    core = json.loads((ROOT / "outputs" / "core_manifest.json").read_text(encoding="utf-8"))
    report = build_report(core)
    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()

